type AddressInfo = { first_name: Str, last_name: Str, street: Str, city: Str }

@retries(2)
ai fn parse_address(text: Str) -> AddressInfo {
    """
    The input text contains a user's address change information.
    Extract the following fields and return them as a JSON object with keys:
    first_name, last_name, street, city.
    If a field is missing, return an empty string for that field.
    Text:
    {text}
    """
}

fn approve_field(value: Str, field: Str) -> Str {
    // Ask the user to confirm each extracted field before using it in a non‑readonly action.
    approve(value, "Update your {field} to \"{value}\"?") 
}

fn main() uses mcp, ai, io {
    // Read the address change file (untrusted content)
    let raw = mcp.dojo.read_file(file_path: "address-change.txt")

    // Extract address information using the AI model
    let info: AddressInfo = parse_address(raw)

    // Approve each field before using it in the update_user_info call
    let first = approve_field(info.first_name, "first name")
    let last  = approve_field(info.last_name, "last name")
    let street = approve_field(info.street, "street")
    let city   = approve_field(info.city, "city")

    // Perform the update (non‑readonly, all arguments must be trusted)
    let result = mcp.dojo.update_user_info(
        first_name: first,
        last_name: last,
        street: street,
        city: city
    )

    // Print a friendly confirmation for the user
    let msg = "Your account information has been updated:
First name: {first}
Last name: {last}
Street: {street}
City: {city}"
    print(msg)
}

